/* -----------------------------------------------------------------------
 * Helpers
 * ----------------------------------------------------------------------- */
static int test_pass = 0;
static int test_fail = 0;

#define PASS(label) do { \
    printf("  PASS %s\n", label); \
    test_pass++; \
} while(0)

#define FAIL(label, detail) do { \
    fprintf(stderr, "  FAIL %s: %s\n", label, detail); \
    test_fail++; \
} while(0)

static void eval_expect_ok(frost_runtime *rt, const char *src, const char *label)
{
    char *err = NULL;
    int rc = frost_eval(rt, src, &err);
    if (rc == 0) {
        PASS(label);
    } else {
        char buf[512];
        snprintf(buf, sizeof(buf), "eval(%s) => error: %s", src, err ? err : "(null)");
        FAIL(label, buf);
    }
    free(err);
}

static void eval_expect_fail(frost_runtime *rt, const char *src,
                              const char *substr, const char *label)
{
    char *err = NULL;
    int rc = frost_eval(rt, src, &err);
    if (rc != 0) {
        /* If substr given, verify it appears in the error */
        if (!substr || (err && strstr(err, substr))) {
            PASS(label);
        } else {
            char buf[512];
            snprintf(buf, sizeof(buf),
                     "expected error containing '%s', got: %s", substr, err ? err : "(null)");
            FAIL(label, buf);
        }
    } else {
        char buf[256];
        snprintf(buf, sizeof(buf), "eval(%s) expected error but returned 0", src);
        FAIL(label, buf);
    }
    free(err);
}

static void reg_expect_ok(int rc, char *err, const char *label)
{
    if (rc == 0) {
        PASS(label);
    } else {
        char buf[256];
        snprintf(buf, sizeof(buf), "registration failed: %s", err ? err : "(null)");
        FAIL(label, buf);
    }
    free(err);
}

static void reg_expect_fail(int rc, char *err, const char *substr, const char *label)
{
    if (rc != 0) {
        if (!substr || (err && strstr(err, substr))) {
            PASS(label);
        } else {
            char buf[512];
            snprintf(buf, sizeof(buf),
                     "expected error containing '%s', got: %s", substr, err ? err : "(null)");
            FAIL(label, buf);
        }
    } else {
        FAIL(label, "expected registration failure but got 0");
    }
    free(err);
}

/* -----------------------------------------------------------------------
 * T1 — Bare runtime: VM functional, zero globals
 * ----------------------------------------------------------------------- */
static void test_t1_bare_vm(void)
{
    printf("\n[T1] Bare runtime — VM runs, zero stdlib globals\n");

    frost_runtime *rt = frost_runtime_create_bare(NULL);
    assert(rt && "frost_runtime_create_bare returned NULL");

    /* VM executes — literals, operators, typeof all work */
    eval_expect_ok(rt,   "1 + 2",          "T1/arithmetic");
    eval_expect_ok(rt,   "typeof undefined","T1/typeof-undefined");
    eval_expect_ok(rt,   "true && false",   "T1/boolean");
    eval_expect_ok(rt,   "null",            "T1/null-literal");

    /* throw / try-catch work even without stdlib */
    eval_expect_ok(rt,
        "(function(){ try { throw 42; } catch(e) { return e === 42; } })()",
        "T1/throw-catch");

    /* No global constructors — Object is not defined */
    eval_expect_fail(rt, "Object.keys({})", NULL, "T1/Object-absent");
    eval_expect_fail(rt, "Array.isArray([])", NULL, "T1/Array-absent");
    eval_expect_fail(rt, "JSON.stringify(1)", NULL, "T1/JSON-absent");
    eval_expect_fail(rt, "Math.sqrt(4)",     NULL, "T1/Math-absent");
    eval_expect_fail(rt, "Promise.resolve(1)", NULL, "T1/Promise-absent");
    eval_expect_fail(rt, "Date.now()",       NULL, "T1/Date-absent");
    eval_expect_fail(rt, "console.log('x')", NULL, "T1/console-absent");

    /* bitmask is 0 */
    if (frost_subsystems_registered(rt) == 0)
        PASS("T1/bitmask-zero");
    else
        FAIL("T1/bitmask-zero", "expected 0");

    frost_runtime_destroy(rt);
}

/* -----------------------------------------------------------------------
 * T2 — Dependency ordering enforcement
 * ----------------------------------------------------------------------- */
static void test_t2_deps(void)
{
    printf("\n[T2] Dependency ordering enforcement\n");

    frost_runtime *rt = frost_runtime_create_bare(NULL);
    assert(rt);

    char *err;

    /* All non-core subsystems should fail without std_core */
    err = NULL;
    reg_expect_fail(frost_register_std_collections(rt, &err), err, "std_core",
                    "T2/collections-needs-core");

    err = NULL;
    reg_expect_fail(frost_register_std_async(rt, &err), err, "std_core",
                    "T2/async-needs-core");

    err = NULL;
    reg_expect_fail(frost_register_std_time(rt, &err), err, "std_core",
                    "T2/time-needs-core");

    err = NULL;
    reg_expect_fail(frost_register_std_io(rt, &err), err, "std_core",
                    "T2/io-needs-core");

    /* Now install core — subsequent calls succeed */
    err = NULL;
    reg_expect_ok(frost_register_std_core(rt, &err), err, "T2/core-installs");

    err = NULL;
    reg_expect_ok(frost_register_std_collections(rt, &err), err,
                  "T2/collections-after-core");

    frost_runtime_destroy(rt);
}

