/* -----------------------------------------------------------------------
 * T4 — std_core correctness
 * ----------------------------------------------------------------------- */
static void test_t4_core(void)
{
    printf("\n[T4] std_core — Object, Array, String, Math, eval, RegExp, JSON, Proxy, Map\n");

    frost_runtime *rt = frost_runtime_create_bare(NULL);
    assert(rt);

    char *err = NULL;
    reg_expect_ok(frost_register_std_core(rt, &err), err, "T4/core-register");

    /* Object */
    eval_expect_ok(rt, "Object.keys({a:1,b:2}).length === 2", "T4/Object.keys");
    eval_expect_ok(rt, "Object.assign({}, {x:1}).x === 1",    "T4/Object.assign");

    /* Array */
    eval_expect_ok(rt, "[1,2,3].map(x=>x*2).join(',') === '2,4,6'", "T4/Array.map");
    eval_expect_ok(rt, "Array.isArray([])",                          "T4/Array.isArray");
    eval_expect_ok(rt, "[1,2,3].filter(x=>x>1).length === 2",       "T4/Array.filter");

    /* String */
    eval_expect_ok(rt, "'hello'.toUpperCase() === 'HELLO'", "T4/String.toUpperCase");
    eval_expect_ok(rt, "'  x  '.trim() === 'x'",            "T4/String.trim");

    /* Math */
    eval_expect_ok(rt, "Math.sqrt(9) === 3",   "T4/Math.sqrt");
    eval_expect_ok(rt, "Math.max(1,2,3) === 3","T4/Math.max");
    eval_expect_ok(rt, "Math.abs(-5) === 5",   "T4/Math.abs");
    eval_expect_ok(rt, "Math.floor(1.9) === 1","T4/Math.floor");

    /* Number */
    eval_expect_ok(rt, "Number.isFinite(42)", "T4/Number.isFinite");
    eval_expect_ok(rt, "Number.isNaN(NaN)",   "T4/Number.isNaN");
    eval_expect_ok(rt, "(1.5).toFixed(1) === '1.5'", "T4/toFixed");

    /* eval() */
    eval_expect_ok(rt, "eval('1+1') === 2", "T4/eval");

    /* RegExp */
    eval_expect_ok(rt, "/^hello/.test('hello world')", "T4/regexp-literal");
    eval_expect_ok(rt, "new RegExp('\\\\d+').test('42')", "T4/regexp-ctor");
    eval_expect_ok(rt, "'abc123'.match(/\\d+/)[0] === '123'", "T4/string-match");

    /* JSON */
    eval_expect_ok(rt, "JSON.stringify({x:1}) === '{\"x\":1}'", "T4/JSON.stringify");
    eval_expect_ok(rt, "JSON.parse('{\"x\":1}').x === 1",       "T4/JSON.parse");

    /* Proxy */
    eval_expect_ok(rt,
        "(function(){"
        "  var p = new Proxy({}, { get: function(_,k){ return k==='foo'?42:undefined; } });"
        "  return p.foo === 42;"
        "})()",
        "T4/Proxy");

    /* Map / Set */
    eval_expect_ok(rt, "(function(){ var m=new Map(); m.set('k',99); return m.get('k')===99; })()",
                   "T4/Map");
    eval_expect_ok(rt, "(function(){ var s=new Set([1,2,2,3]); return s.size===3; })()",
                   "T4/Set");

    /* Error hierarchy */
    eval_expect_ok(rt,
        "(function(){ try { null.x; } catch(e){ return e instanceof TypeError; } })()",
        "T4/TypeError");
    eval_expect_ok(rt,
        "(function(){ try { undeclared; } catch(e){ return e instanceof ReferenceError; } })()",
        "T4/ReferenceError");

    /* Symbol */
    eval_expect_ok(rt, "typeof Symbol('x') === 'symbol'", "T4/Symbol");
    eval_expect_ok(rt,
        "(function(){ var s=Symbol('tag'); var o={}; o[s]=1; return o[s]===1; })()",
        "T4/Symbol-as-key");

    frost_runtime_destroy(rt);
}

