    eval_expect_fail(rt, "new Int32Array(4)", NULL, "T10/TypedArray-absent");
    eval_expect_fail(rt, "Date.now()",        NULL, "T10/Date-absent");
    eval_expect_fail(rt, "console.log('x')",  NULL, "T10/console-absent");

    /* Bitmask check */
    unsigned int reg = frost_subsystems_registered(rt);
    if ((reg & FROST_STD_CORE) && (reg & FROST_STD_ASYNC) &&
        !(reg & FROST_STD_COLLECTIONS) &&
        !(reg & FROST_STD_TIME) &&
        !(reg & FROST_STD_IO))
        PASS("T10/bitmask-selective");
    else
        FAIL("T10/bitmask-selective", "unexpected bitmask");

    frost_runtime_destroy(rt);
}

/* -----------------------------------------------------------------------
 * T11 — Multi-runtime isolation: different stdlib per runtime
 * ----------------------------------------------------------------------- */
static void test_t11_isolation(void)
{
    printf("\n[T11] Multi-runtime isolation — different stdlib per runtime\n");

    /* rt_io: has io, no Date */
    frost_runtime *rt_io = frost_runtime_create_bare(NULL);
    assert(rt_io);
    {
        char *err;
        err = NULL; frost_register_std_core(rt_io, &err); free(err);
        err = NULL; frost_register_std_io(rt_io, &err);   free(err);
    }

    /* rt_time: has Date, no console */
    frost_runtime *rt_time = frost_runtime_create_bare(NULL);
    assert(rt_time);
    {
        char *err;
        err = NULL; frost_register_std_core(rt_time, &err); free(err);
        err = NULL; frost_register_std_time(rt_time, &err); free(err);
    }

    /* rt_full: frost_runtime_create (Stage 1 compat) */
    frost_runtime *rt_full = frost_runtime_create(NULL);
    assert(rt_full);

    /* rt_io checks */
    eval_expect_ok(rt_io, "typeof console.log === 'function'","T11/rt_io-console-present");
    eval_expect_fail(rt_io, "Date.now()", NULL,               "T11/rt_io-Date-absent");

    /* rt_time checks */
    eval_expect_ok(rt_time, "typeof Date.now() === 'number'", "T11/rt_time-Date-present");
    eval_expect_fail(rt_time, "console.log('x')", NULL,       "T11/rt_time-console-absent");

    /* rt_full checks */
    eval_expect_ok(rt_full, "typeof Date.now() === 'number'", "T11/rt_full-Date");
    eval_expect_ok(rt_full, "JSON.stringify([1])",            "T11/rt_full-JSON");
    eval_expect_ok(rt_full, "typeof Promise === 'function'",  "T11/rt_full-Promise");

    /* Global isolation: sentinel set in rt_io invisible in rt_time */
    {
        char *err = NULL;
        frost_eval(rt_io, "var __SENTINEL2__ = 777;", &err); free(err);
        eval_expect_fail(rt_time, "__SENTINEL2__", NULL, "T11/global-isolation");
    }

    frost_runtime_destroy(rt_io);
    frost_runtime_destroy(rt_time);
    frost_runtime_destroy(rt_full);
}

/* -----------------------------------------------------------------------
 * T12 — Bitmask introspection
 * ----------------------------------------------------------------------- */
static void test_t12_bitmask(void)
{
    printf("\n[T12] Bitmask introspection\n");

    frost_runtime *rt = frost_runtime_create_bare(NULL);
    assert(rt);

    if (frost_subsystems_registered(rt) == 0)
        PASS("T12/bare-is-zero");
    else
        FAIL("T12/bare-is-zero", "expected 0");

    char *err;

    err = NULL; frost_register_std_core(rt, &err); free(err);
    if (frost_subsystems_registered(rt) == FROST_STD_CORE)
        PASS("T12/after-core");
    else
        FAIL("T12/after-core", "bitmask wrong");

    err = NULL; frost_register_std_collections(rt, &err); free(err);
    if (frost_subsystems_registered(rt) & FROST_STD_COLLECTIONS)
        PASS("T12/after-collections");
    else
        FAIL("T12/after-collections", "COLLECTIONS bit not set");

    err = NULL; frost_register_std_async(rt, &err); free(err);
    err = NULL; frost_register_std_time(rt, &err);  free(err);
    err = NULL; frost_register_std_io(rt, &err);    free(err);

    unsigned int all = FROST_STD_CORE | FROST_STD_COLLECTIONS |
                       FROST_STD_ASYNC | FROST_STD_TIME | FROST_STD_IO;
    if (frost_subsystems_registered(rt) == all)
        PASS("T12/all-bits-set");
    else
        FAIL("T12/all-bits-set", "bitmask incomplete");

    /* NULL runtime returns 0 — no crash */
    if (frost_subsystems_registered(NULL) == 0)
        PASS("T12/null-returns-zero");
    else
        FAIL("T12/null-returns-zero", "expected 0 for NULL");

    frost_runtime_destroy(rt);
}

/* -----------------------------------------------------------------------
 * T13 — frost_runtime_create() (Stage 1) bitmask compatibility
 * ----------------------------------------------------------------------- */
static void test_t13_compat(void)
{
    printf("\n[T13] Stage 1 compat — frost_runtime_create() has full bitmask\n");

    frost_runtime *rt = frost_runtime_create(NULL);
    assert(rt);

    unsigned int reg = frost_subsystems_registered(rt);
    unsigned int expected = FROST_STD_CORE | FROST_STD_COLLECTIONS |
                            FROST_STD_ASYNC | FROST_STD_TIME;

    /* IO is NOT set because JS_NewContext doesn't call js_std_add_helpers */
    if ((reg & expected) == expected)
        PASS("T13/full-bitmask-set");
    else
        FAIL("T13/full-bitmask-set", "expected core|collections|async|time bits");

    /* Full runtime has everything */
    eval_expect_ok(rt, "typeof Promise === 'function'",    "T13/Promise");
    eval_expect_ok(rt, "typeof Date.now() === 'number'",   "T13/Date");
    eval_expect_ok(rt, "new Int32Array(2).length === 2",   "T13/TypedArray");
    eval_expect_ok(rt, "JSON.stringify({a:1})",            "T13/JSON");
    eval_expect_ok(rt, "btoa('stage1')",                   "T13/btoa");

    /* Adding IO to a full runtime is still idempotent on the non-IO bits */
    char *err = NULL;
    reg_expect_ok(frost_register_std_io(rt, &err), err, "T13/io-add-to-full");
    eval_expect_ok(rt, "typeof console.log === 'function'","T13/console-after-add");

    frost_runtime_destroy(rt);
}

/* -----------------------------------------------------------------------
 * Main
 * ----------------------------------------------------------------------- */
int main(void)
{
    printf("FrostCore Stage 2 — Subsystem Test Suite\n");
    printf("==========================================\n");

    test_t1_bare_vm();
    test_t2_deps();
    test_t3_idempotent();
    test_t4_core();
    test_t5_collections();
    test_t6_async();
    test_t7_time();
    test_t8_io();
    test_t9_all();
    test_t10_selective();
    test_t11_isolation();
    test_t12_bitmask();
    test_t13_compat();

    printf("\n==========================================\n");
    printf("Results: %d passed, %d failed\n", test_pass, test_fail);

    if (test_fail > 0) {
        fprintf(stderr, "\nSome tests FAILED.\n");
        return 1;
    }
    printf("All subsystem tests PASSED.\n");
    return 0;
}

